    def self.names = ICONS.keys

    def initialize(name, label: nil, **html_options)
      @name = name.to_sym
      @label = label
      @html_options = html_options
      raise ArgumentError, "Unknown icon #{name.inspect}. Known: #{ICONS.keys.join(", ")}" unless ICONS.key?(@name)
    end

    def call
      style, view_box, markup = ICONS.fetch(@name)
      attrs = { xmlns: "http://www.w3.org/2000/svg", viewBox: view_box }
      attrs.merge!(style == :outline ? { fill: "none", stroke: "currentColor" } : { fill: "currentColor" })
      attrs[:class] = @html_options[:class] || "h-5 w-5"
      if @label
        attrs.merge!(role: "img", "aria-label": @label)
      else
        attrs[:"aria-hidden"] = "true"
      end
      attrs.merge!(@html_options.except(:class))
      content_tag(:svg, markup.html_safe, attrs)
    end
